{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A1",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "date that defines the start of the assembly",
          "motivo": "premissa_alterada",
          "correto_seria": "A montagem começa em D22, quando o conjunto da MetalForm fica disponível; a entrega da GearWorks em D20 deixa 2 dias de folga e não define o início."
        }
      ],
      "observacao": "A data de entrega da GearWorks permanece D20, mas deixou de determinar o início da montagem."
    },
    {
      "trecho_id": "ACTION_LOG.A2",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "D25, data em que o protótipo fica disponível",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D27; os testes começam então e a validação termina em D37, dentro da franquia de 10 dias."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A3",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A ação está ligada à fabricação das peças da MetalForm, cujo prazo de entrega mudou, mas as informações do trecho continuam corretas."
    },
    {
      "trecho_id": "ACTION_LOG.A4",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a ser preenchido entre D35 e D38",
          "motivo": "valor_divergente",
          "correto_seria": "A documentação será preenchida entre D37 e D40."
        },
        {
          "citacao": "protótipo disponível em D24",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D27."
        },
        {
          "citacao": "validação concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R1",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "que está no caminho crítico sem folga",
          "motivo": "premissa_alterada",
          "correto_seria": "A GearWorks tem 2 dias de folga; a entrega da MetalForm em D22 determina o início da montagem."
        },
        {
          "citacao": "cada dia de atraso adia a Liberação de engenharia (D40) e custa R$ 300,00 de gestão e instalação",
          "motivo": "premissa_alterada",
          "correto_seria": "Atrasos da GearWorks de até 2 dias não alteram o cronograma; além dessa folga, cada dia adicional adia a liberação e acrescenta R$ 300,00 de gestão e instalação."
        },
        {
          "citacao": "D40",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia está prevista para D42."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R2",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O risco continua pertinente após o deslocamento do cronograma: a validação está prevista para D37 e a duração planejada entre protótipo e validação permanece em 10 dias."
    },
    {
      "trecho_id": "RISK_REGISTER.R3",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A ElecBoard tem 3 dias de folga, pois entrega em D19 e a montagem começa em D22."
        },
        {
          "citacao": "um atraso maior que isso passa a determinar o início da montagem",
          "motivo": "premissa_alterada",
          "correto_seria": "Um atraso superior a 3 dias passa a determinar o início da montagem."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R4",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O risco está ligado às peças da MetalForm, cujo prazo mudou, mas a possibilidade de reprovação, o custo estimado e a opinião registrada não se tornam factualmente incorretos."
    },
    {
      "trecho_id": "DECISION_LOG.D1",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico da decisão, preservado conforme a regra para o Decision Log."
    },
    {
      "trecho_id": "DECISION_LOG.D2",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico da decisão, preservado conforme a regra para o Decision Log."
    },
    {
      "trecho_id": "DECISION_LOG.D3",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico da decisão, preservado conforme a regra para o Decision Log."
    }
  ]
}
